private static Format getFormat(MediaFormat mediaFormat){
  ImmutableList.Builder<byte[]> csdBuffers=new ImmutableList.Builder<>();
  int csdIndex=0;
  while (true) {
    @Nullable ByteBuffer csdByteBuffer=mediaFormat.getByteBuffer("csd-" + csdIndex);
    if (csdByteBuffer == null) {
      break;
    }
    byte[] csdBufferData=new byte[csdByteBuffer.remaining()];
    csdByteBuffer.get(csdBufferData);
    csdBuffers.add(csdBufferData);
    csdIndex++;
  }
  String mimeType=mediaFormat.getString(MediaFormat.KEY_MIME);
  Format.Builder formatBuilder=new Format.Builder().setSampleMimeType(mediaFormat.getString(MediaFormat.KEY_MIME)).setInitializationData(csdBuffers.build());
  if (MimeTypes.isVideo(mimeType)) {
    formatBuilder.setWidth(mediaFormat.getInteger(MediaFormat.KEY_WIDTH)).setHeight(mediaFormat.getInteger(MediaFormat.KEY_HEIGHT));
  }
 else   if (MimeTypes.isAudio(mimeType)) {
    formatBuilder.setChannelCount(mediaFormat.getInteger(MediaFormat.KEY_CHANNEL_COUNT)).setSampleRate(mediaFormat.getInteger(MediaFormat.KEY_SAMPLE_RATE)).setPcmEncoding(MEDIA_CODEC_PCM_ENCODING);
  }
  return formatBuilder.build();
}
